#!/usr/bin/env bash
#
# Generates a release keystore + keystore.properties for Spam Guard.
#
# The keystore is what makes a build publishable: Cafe Bazaar (and every other
# store) rejects APKs/AABs signed with the throwaway debug key. Keep the
# generated files secret and back them up — losing the keystore means you can
# never ship an update for the same applicationId.
#
# Usage:
#   scripts/generate-keystore.sh            # generate if missing
#   FORCE=1 scripts/generate-keystore.sh    # overwrite existing files
#
# Overridable via environment:
#   KEY_ALIAS     key alias               (default: spamguard)
#   KEYSTORE_DIR  output directory        (default: keystore)
#   DNAME         certificate subject     (default: sensible Spam Guard defaults)

set -euo pipefail

cd "$(dirname "$0")/.."

KEY_ALIAS="${KEY_ALIAS:-spamguard}"
KEYSTORE_DIR="${KEYSTORE_DIR:-keystore}"
KEYSTORE_FILE="${KEYSTORE_DIR}/release.jks"
PROPERTIES_FILE="keystore.properties"
DNAME="${DNAME:-CN=Spam Guard, OU=Spam Guard, O=Spam Guard, L=Tehran, ST=Tehran, C=IR}"

if [[ "${FORCE:-0}" != "1" && ( -f "$KEYSTORE_FILE" || -f "$PROPERTIES_FILE" ) ]]; then
    echo "error: $KEYSTORE_FILE or $PROPERTIES_FILE already exists." >&2
    echo "       Re-run with FORCE=1 to overwrite (this cannot be undone)." >&2
    exit 1
fi

command -v keytool >/dev/null 2>&1 || {
    echo "error: 'keytool' not found. Install a JDK 17+ and retry." >&2
    exit 1
}

# 24-byte base64 password.
generate_password() {
    if command -v openssl >/dev/null 2>&1; then
        openssl rand -base64 24
    else
        head -c 24 /dev/urandom | base64
    fi
}

STORE_PASSWORD="$(generate_password)"
KEY_PASSWORD="$STORE_PASSWORD"

mkdir -p "$KEYSTORE_DIR"

keytool -genkeypair \
    -v \
    -keystore "$KEYSTORE_FILE" \
    -alias "$KEY_ALIAS" \
    -keyalg RSA \
    -keysize 4096 \
    -validity 10000 \
    -storepass "$STORE_PASSWORD" \
    -keypass "$KEY_PASSWORD" \
    -dname "$DNAME"

umask 077
cat > "$PROPERTIES_FILE" <<EOF
# Generated by scripts/generate-keystore.sh — DO NOT COMMIT.
# Paths are relative to the repository root.
storeFile=$KEYSTORE_FILE
storePassword=$STORE_PASSWORD
keyAlias=$KEY_ALIAS
keyPassword=$KEY_PASSWORD
EOF

echo
echo "Created:"
echo "  keystore : $KEYSTORE_FILE"
echo "  config   : $PROPERTIES_FILE"
echo
echo "Both are git-ignored. Back them up somewhere safe (password manager,"
echo "encrypted drive) before you publish — without the keystore you cannot"
echo "ship updates for this applicationId."
